package com.learningspace;
import android.graphics.*;
public final class WidgetGraphics {
 public static Bitmap bar(int width,int height,int percent,boolean dark){Bitmap b=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(dark?0xff3c5042:0xffdbe5d2);c.drawRoundRect(0,0,width,height,height/2f,height/2f,p);p.setColor(dark?0xffb8d883:0xff568348);if(percent>0)c.drawRoundRect(0,0,width*Math.min(100,percent)/100f,height,height/2f,height/2f,p);return b;}
 public static Bitmap ring(int size,int percent,boolean dark){Bitmap b=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);float stroke=size*.11f,margin=stroke/2+2;p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(stroke);p.setColor(dark?0xff3c5042:0xffdbe5d2);RectF bounds=new RectF(margin,margin,size-margin,size-margin);c.drawOval(bounds,p);p.setStrokeCap(Paint.Cap.ROUND);p.setColor(dark?0xffb8d883:0xff568348);if(percent>0)c.drawArc(bounds,-90,Math.min(100,percent)*3.6f,false,p);p.setStyle(Paint.Style.FILL);p.setColor(dark?0xffe8f1dd:0xff294331);p.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));p.setTextAlign(Paint.Align.CENTER);p.setTextSize(size*.24f);c.drawText(percent+"%",size/2f,size*.52f,p);p.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));p.setTextSize(size*.105f);c.drawText("daily goal",size/2f,size*.68f,p);return b;}
 public static Bitmap week(int width,int height,WidgetMetrics m,boolean dark){Bitmap b=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);float gap=width/7f,baseline=height*.75f;int max=Math.max(1,m.goal);for(int n:m.week)max=Math.max(max,n);String[] labels={"M","T","W","T","F","S","S"};for(int i=0;i<7;i++){float x=gap*i+gap*.25f,bar=Math.max(height*.04f,(float)m.week[i]/max*height*.63f);p.setColor(dark?(i==6?0xffb9d788:0xff759a69):(i==6?0xff537c48:0xffacc39b));c.drawRoundRect(x,baseline-bar,x+gap*.5f,baseline,width*.025f,width*.025f,p);p.setColor(dark?0xffb9c9b1:0xff52664e);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(height*.13f);int dow=java.time.LocalDate.parse(m.days[i]).getDayOfWeek().getValue();c.drawText(labels[dow-1],x+gap*.25f,height*.96f,p);}return b;}
}
